from pathlib import Path
import re,json
ROOT=Path(__file__).resolve().parents[2]
def replace(id,old,new):
 p=ROOT/'items'/(id+'.md'); s=p.read_text(); assert old in s,(id,old[:70]); p.write_text(s.replace(old,new,1))
def step(id,num,text):
 p=ROOT/'items'/(id+'.md'); s=p.read_text(); pattern=r'^'+re.escape(num)+r' [\s\S]*?(?=\n\n|\Z)'; s,n=re.subn(pattern,lambda _:num+' '+text,s,count=1,flags=re.M); assert n==1,id; p.write_text(s)

step('lem-cm-lattice-shell-count-and-weight-sums','3.1',r'Put $c:=\sqrt3/2<1$. The disjoint unit boxes $H_k$ for $m\le|k|_2<m+1$ lie in the annulus $m-c<|x|_2<m+1+c$, since $|x-k|_2\le c$. Its volume is at most $\frac43\pi[(m+1+c)^3-(m-c)^3]$ by [F1] and [F4]. (Using the open inner ball gives the same upper bound, so no assertion about sphere measure is needed.) By finite additivity each box has volume one, so the shell count is bounded by this volume. Since $m\ge1$ and $c<1$, the difference of cubes is at most $(m+2)^3-(m-1)^3=9m^2+9m+9\le27(m+1)^2$. Thus the shell count is at most $36\pi(m+1)^2\le240(m+1)^2$, preserving the stated $C_*=240$. [step 1.1, F1, F4, algebra]')
replace('lem-cm-integral-and-ftc-for-continuous-normed-space-curves',r'Taking $Q^{(j)}=P^{(k)}$ for fixed $k$ and letting $j\to\infty$ shows that $(S_{P^{(j)}})$ is Cauchy',r'For two indices $j,k$ the same common-refinement estimate gives $\|S_{P^{(j)}}-S_{P^{(k)}}\|\le2(b-a)\omega(\max(\mathrm{mesh}(P^{(j)}),\mathrm{mesh}(P^{(k)})))\to0$ as both indices tend to infinity, so $(S_{P^{(j)}})$ is Cauchy')
step('lem-fourier-lattice-sobolev-embedding','1.2',r'**Nonempty open sets have positive measure.** For nonempty open $U\subseteq\mathbb T^3$, its inverse image under the surjective quotient map $Q:\mathbb R^3\to\mathbb T^3$ is nonempty open by [F6]. Choose a point $y$ in it with no integer coordinate: such points meet every open box, because each coordinate interval contains a noninteger real. Translate $y$ by an integer vector to $z\in(0,1)^3$; periodicity leaves $z\in Q^{-1}[U]$. Openness gives a sufficiently small nonempty box $I$ about $z$ contained in $Q^{-1}[U]\cap(0,1)^3$. Its volume is positive, so $dx(U)=\lambda_3(Q^{-1}[U]\cap[0,1)^3)\ge\lambda_3(I)>0$ by [F5] and [F6]. [F5, F6]')
replace('lem-discrete-young-and-sobolev-product',r'[F3] If $\sigma>3/2$ then $\sum_kw_k^{2\sigma}|c(k)|^2<+\infty$ implies $\sum_kw_k^{\sigma}|c(k)|<\infty$, with $\sum_kw_k^{\sigma}|c(k)|\le W_\sigma\bigl(\sum_kw_k^{2\sigma}|c(k)|^2\bigr)^{1/2}$, and $\sum_k|c(k)|\le W_\sigma(\cdots)^{1/2}$',r'[F3] If $\sigma>3/2$ then $\sum_kw_k^{2\sigma}|c(k)|^2<+\infty$ implies $\sum_k|c(k)|\le W_\sigma\bigl(\sum_kw_k^{2\sigma}|c(k)|^2\bigr)^{1/2}$')
replace('lem-discrete-young-and-sobolev-product','[F5] If',r'[F4] Uniformly bounded pointwise-convergent functions on the finite-measure torus have convergent integrals ([[cor-bounded-convergence-on-a-finite-measure-space]]); Fourier coefficient integrals are such integrals after multiplication by the bounded character.'+'\n\n'+'[F5] If')
step('lem-discrete-young-and-sobolev-product','3.1',r'Applying Young to the two convolutions of step 1.2, using the change of variable $l\mapsto k-l$ to commute the factors in the first, gives $\|fg\|_{H^\sigma}\le2^{\sigma-1}(\|A\|_{\ell^2}\|B\|_{\ell^1}+\|A^{\prime}\|_{\ell^1}\|B^{\prime}\|_{\ell^2})$. Thus $\|A\|_2=\|f\|_{H^\sigma}$, $\|B^{\prime}\|_2=\|g\|_{H^\sigma}$, while [F3] gives $\|A^{\prime}\|_1\le W_\sigma\|f\|_{H^\sigma}$ and $\|B\|_1\le W_\sigma\|g\|_{H^\sigma}$. Therefore $\|fg\|_{H^\sigma}\le2^\sigma W_\sigma\|f\|_{H^\sigma}\|g\|_{H^\sigma}$; the finite weighted coefficient norm also proves $fg\in H^\sigma$. This is claim 2. [step 1.2, step 2.1, F3]')
replace('lem-discrete-young-and-sobolev-product',r'\le2W_\sigma\|f\|_{H^\sigma}\|g\|_{H^{\sigma+1}}',r'\le C_\sigma\|f\|_{H^\sigma}\|g\|_{H^{\sigma+1}}')
